<template>
  <academy-layout ref="layout" title="机构工作台">
    <view v-if="loading" class="academy-skeleton" />
    <view v-else-if="error" class="academy-state"><text class="academy-state__title">无法进入机构工作台</text><text class="academy-state__note">{{ error }}</text><view class="academy-actions access-actions"><view class="academy-button academy-button--secondary" @tap="load">重新校验</view><view class="academy-button" @tap="goVerify">机构认证</view></view></view>
    <template v-else>
      <view v-if="!consoleData.canWrite" class="read-only-banner"><text>当前角色为只读访问</text><text>写操作仅机构管理员或运营经理可用</text></view>
      <view class="academy-metrics"><view class="academy-metric"><text class="academy-metric__value">{{ consoleData.metrics.leads }}</text><text class="academy-metric__label">新增线索</text></view><view class="academy-metric"><text class="academy-metric__value">{{ consoleData.metrics.pendingVisits }}</text><text class="academy-metric__label">待确认试听</text></view><view class="academy-metric"><text class="academy-metric__value">{{ consoleData.metrics.activeStudents }}</text><text class="academy-metric__label">在训学员</text></view></view>
      <view class="academy-section"><view class="academy-section__head"><view><text class="academy-section__title">运营待办</text><text class="academy-section__note">所有写操作均需二次确认</text></view></view><view class="academy-list"><view class="academy-row"><view class="academy-row__main"><text class="academy-row__title">排课冲突</text><text class="academy-row__note">{{ consoleData.scheduleConflict ? '教练和场地时段重叠，需要确认调整' : '当前没有排课冲突' }}</text></view><view v-if="consoleData.scheduleConflict" class="academy-button academy-button--secondary academy-button--small" :class="{ 'academy-button--disabled': !consoleData.canWrite }" @tap="prepareWrite('resolve_schedule', {}, '确认解决排课冲突', '将采用系统推荐的备选教练与场地时段。')">处理</view><text v-else class="academy-tag academy-tag--accent">已处理</text></view></view></view>
      <view class="academy-section"><view class="academy-section__head"><view><text class="academy-section__title">招生线索</text><text class="academy-section__note">仅显示归属本机构且具备查看权限的线索</text></view></view><view v-if="!leads.length" class="academy-state"><text class="academy-state__title">暂无待跟进线索</text><text class="academy-state__note">咨询、试听和报名线索会在这里汇总</text></view><view v-else class="academy-list"><view v-for="lead in leads" :key="lead.id" class="academy-row"><view class="academy-row__main"><text class="academy-row__title">{{ lead.name || lead.title }}</text><text class="academy-row__note">{{ lead.channel || '平台咨询' }} · {{ lead.updatedAt || '刚刚同步' }}</text><text class="academy-tag">{{ lead.status || '待跟进' }}</text></view><view class="academy-button academy-button--secondary academy-button--small" :class="{ 'academy-button--disabled': !consoleData.canWrite }" @tap="prepareWrite('update_lead', { id: lead.id, status: 'contacted' }, '确认跟进线索', '将标记该线索为已联系，并写入跟进记录。')">标记跟进</view></view></view></view>
      <view class="academy-section"><view class="academy-section__head"><text class="academy-section__title">试听预约</text></view><view v-if="!consoleData.visits.length" class="academy-state"><text class="academy-state__title">暂无预约记录</text><text class="academy-state__note">学员提交预约后会显示在这里</text></view><view v-else class="academy-list"><view v-for="visit in consoleData.visits" :key="visit.id" class="academy-row"><view class="academy-row__main"><text class="academy-row__title">{{ visit.name }} · {{ visit.date }}</text><text class="academy-row__note">{{ visit.slot }} · {{ visit.partySize }} 人 · {{ visit.phone }}</text><text class="academy-tag" :class="visit.status === 'confirmed' ? 'academy-tag--accent' : visit.status === 'cancelled' ? 'academy-tag--danger' : 'academy-tag--warn'">{{ statusLabel(visit.status) }}</text></view><view v-if="['pending', 'rescheduled'].includes(visit.status)" class="academy-button academy-button--small" :class="{ 'academy-button--disabled': !consoleData.canWrite }" @tap="prepareWrite('confirm_visit', { id: visit.id }, '确认试听预约', `确认 ${visit.name} 在 ${visit.date} ${visit.slot} 到访。`)">确认预约</view></view></view></view>
      <view class="academy-section"><view class="academy-section__head"><text class="academy-section__title">排课与签到</text></view><view v-if="!schedules.length" class="academy-state"><text class="academy-state__title">暂无待管理排课</text><text class="academy-state__note">排课数据由机构课程系统同步</text></view><view v-else class="academy-list"><view v-for="schedule in schedules" :key="schedule.id" class="academy-row"><view class="academy-row__main"><text class="academy-row__title">{{ schedule.courseName || schedule.title }}</text><text class="academy-row__note">{{ schedule.date }} {{ schedule.slot }} · {{ schedule.coachName || '教练待分配' }} · {{ schedule.venue || '场地待分配' }}</text><text v-if="schedule.conflict" class="academy-tag academy-tag--danger">有冲突</text></view><view class="academy-button academy-button--secondary academy-button--small" :class="{ 'academy-button--disabled': !consoleData.canWrite }" @tap="prepareWrite('update_schedule', { id: schedule.id, action: schedule.conflict ? 'resolve' : 'confirm' }, schedule.conflict ? '确认调整排课' : '确认排课', '服务端会再次检查教练、场地和学员时间冲突。')">{{ schedule.conflict ? '调整' : '确认' }}</view></view></view></view>
      <view class="academy-section"><view class="academy-section__head"><view><text class="academy-section__title">学员与签到</text><text class="academy-section__note">状态变更同步学习档案，删除仅允许服务端软删除</text></view></view><view v-if="!students.length" class="academy-state"><text class="academy-state__title">暂无在训学员</text><text class="academy-state__note">学员报名确认后会显示在这里</text></view><view v-else class="academy-list"><view v-for="student in students" :key="student.id" class="academy-row"><view class="academy-row__main"><text class="academy-row__title">{{ student.name }}</text><text class="academy-row__note">{{ student.courseName || '课程待分配' }} · {{ student.progress || 0 }}% 进度 · {{ attendanceLabel(student.attendance) }}</text></view><view class="academy-actions"><view class="academy-button academy-button--secondary academy-button--small" :class="{ 'academy-button--disabled': !consoleData.canWrite }" @tap="prepareWrite('attendance', { id: student.id, status: 'present' }, '确认学员签到', '签到会写入机构运营记录和学员学习档案。')">签到</view><view class="academy-button academy-button--secondary academy-button--small" :class="{ 'academy-button--disabled': !consoleData.canWrite }" @tap="prepareWrite('update_student', { id: student.id, status: 'active' }, '保存学员状态', '仅可修改本机构在训学员；服务端会校验当前操作者权限。')">编辑</view></view></view></view></view>
      <view class="academy-section"><view class="academy-section__head"><text class="academy-section__title">考试、口碑与机构资料</text></view><view class="academy-list"><view class="academy-row"><view class="academy-row__main"><text class="academy-row__title">考试安排</text><text class="academy-row__note">{{ consoleData.examSummary || '考试场次和成绩待后端同步' }}</text></view><view class="academy-button academy-button--secondary academy-button--small" :class="{ 'academy-button--disabled': !consoleData.canWrite }" @tap="prepareWrite('publish_exam', {}, '确认发布考试安排', '发布前将由服务端校验考场容量、监考权限和学员范围。')">管理</view></view><view class="academy-row"><view class="academy-row__main"><text class="academy-row__title">口碑与评价</text><text class="academy-row__note">{{ consoleData.reputationSummary || '暂无需回复评价' }}</text></view><view class="academy-button academy-button--secondary academy-button--small" :class="{ 'academy-button--disabled': !consoleData.canWrite }" @tap="prepareWrite('reply_reputation', {}, '确认保存评价回复', '回复内容会经过服务端内容审核后发布。')">处理</view></view><view class="academy-row" @tap="previewInstitution"><view class="academy-row__main"><text class="academy-row__title">机构资料预览</text><text class="academy-row__note">预览当前对外展示的资质、课程、场地和教练信息</text></view><text class="academy-link">预览 ›</text></view></view></view>
      <view v-if="writeError" class="academy-state write-error"><text class="academy-state__title">上次操作未完成</text><text class="academy-state__note">{{ writeError }}</text><view class="academy-button academy-button--secondary" @tap="retryWrite">重试上次操作</view></view>
    </template>
    <confirm-dialog :visible="Boolean(pendingWrite)" :title="pendingWrite?.title || '确认操作'" :message="pendingWrite?.message || ''" @cancel="pendingWrite = null" @confirm="executeWrite" />
  </academy-layout>
</template>

<script>
import AcademyLayout from './AcademyLayout.vue'
import ConfirmDialog from '../../shared/components/ConfirmDialog.vue'
import { academyService } from '../services'
export default {
  name: 'OrgConsolePage', components: { AcademyLayout, ConfirmDialog },
  data() { return { loading: true, error: '', writeError: '', consoleData: null, pendingWrite: null, lastWrite: null } },
  computed: { leads() { return this.consoleData?.leadsList || [] }, schedules() { return this.consoleData?.schedules || [] }, students() { return this.consoleData?.students || [] } },
  mounted() { this.load() },
  methods: {
    async load() { this.loading = true; this.error = ''; try { this.consoleData = await academyService.getOrgConsole() } catch (error) { this.error = error.message } finally { this.loading = false } },
    prepareWrite(action, payload, title, message) { if (!this.consoleData.canWrite) return this.$refs.layout.showToast('当前角色只有查看权限'); this.pendingWrite = { action, payload, title, message } },
    async executeWrite() { const operation = this.pendingWrite; this.pendingWrite = null; if (!operation) return; this.lastWrite = operation; this.writeError = ''; try { await academyService.orgWrite(operation.action, operation.payload); this.$refs.layout.showToast('操作已确认并保存'); this.consoleData = await academyService.getOrgConsole() } catch (error) { this.writeError = error.message; this.$refs.layout.showToast('操作失败，原页面状态已保留') } },
    retryWrite() { if (!this.lastWrite) return; this.pendingWrite = { ...this.lastWrite, title: '重试上次操作', message: '系统会重新校验当前记录，成功后再更新页面。' } },
    statusLabel(status) { return { pending: '待确认', confirmed: '已确认', rescheduled: '改期待确认', cancelled: '已取消' }[status] || status },
    attendanceLabel(status) { return { pending: '待签到', present: '已到课', absent: '缺席' }[status] || '待签到' },
    previewInstitution() { const id = this.consoleData?.institutionId; if (!id) return this.$refs.layout.showToast('机构资料标识待后端返回'); uni.navigateTo({ url: `/pages/academy/institution-detail?id=${id}&preview=1` }) },
    goVerify() { uni.navigateTo({ url: '/pages/profile/account?mode=institution' }) }
  }
}
</script>

<style scoped>
.access-actions { justify-content: center; }.read-only-banner { display: flex; flex-direction: column; gap: 4rpx; margin-bottom: 20rpx; padding: 16rpx 20rpx; border: 1rpx solid var(--academy-warn); border-radius: 12rpx; color: var(--academy-warn); font-size: 21rpx; }.read-only-banner text:first-child { font-weight: 700; }.write-error { border-color: var(--academy-danger); }
</style>
